package de.fitnesscoach.ui.coach;
import android.graphics.Typeface;import android.view.*;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import java.util.*;
public final class CoachChatAdapter extends RecyclerView.Adapter<CoachChatAdapter.Holder>{private final List<CoachMessage>items=new ArrayList<>();public void submit(List<CoachMessage>m){items.clear();items.addAll(m);notifyDataSetChanged();}@NonNull@Override public Holder onCreateViewHolder(@NonNull ViewGroup p,int v){TextView t=new TextView(p.getContext());int pad=(int)(12*p.getResources().getDisplayMetrics().density);t.setPadding(pad,pad,pad,pad);t.setTextIsSelectable(true);return new Holder(t);}@Override public void onBindViewHolder(@NonNull Holder h,int p){CoachMessage m=items.get(p);h.t.setText((m.user?"Du: ":"Coach: ")+m.text);h.t.setTypeface(null,m.user?Typeface.BOLD:Typeface.NORMAL);}@Override public int getItemCount(){return items.size();}static final class Holder extends RecyclerView.ViewHolder{final TextView t;Holder(TextView v){super(v);t=v;}}}
